    bak = Path(str(p) + '.before_20261108b').read_text(encoding='utf-8')
    rm, rp = e['removed'], e['replacement']
    assert bak.count(rm) == 1, (p, rm[:60])
    i = bak.index(rm); cur = RAW[p]
    done = False
    for L in (160, 100, 60, 40, 25, 15):
        pre = bak[max(0, i - L):i]; post = bak[i + len(rm):i + len(rm) + L]
        for old, new in [(pre + rp + post, pre + rm + post), (pre + rp, pre + rm), (rp + post, rm + post)]:
            if (rp or (pre and post)) and old and cur.count(old) == 1 and (old != rp):
                RAW[p] = cur.replace(old, new); done = True; break
        if done: break
    assert done, ('D13-1 anchor not found', p, rm[:80])
    LOG.append(('a D13-1 back (held json)', rel(p), rp if rp else '(anchor: ' + bak[max(0, i - 40):i] + ')', rm, 1))

