def F(t, style):
    if style == 'rep': return re.sub(r'\{\{(.*?)\}\}', r'<span class="src">（\1）</span>', t)
    if style == 'box': return re.sub(r'\{\{(.*?)\}\}', r'<span style="color:#8a8f98;font-size:.8em">（\1）</span>', t)
    if style == 'md': return re.sub(r'\{\{(.*?)\}\}', r'【\1】', t)
    if style == 'note': return re.sub(r'\{\{(.*?)\}\}', r'〔\1〕', t)
    if style == 'en': return re.sub(r'\{\{(.*?)\}\}', r'<span class="src">(\1)</span>', t)
    if style == 'enmd': return re.sub(r'\{\{(.*?)\}\}', r' <sub>(\1)</sub>', t)
    raise ValueError(style)
