# ------------------------------------------------------------------ rule engine
NJ = None
def R_(old, new, files, n=None, why='', regex=False, nmin=1):
    tot = 0
    for p in files:
        if isinstance(p, tuple):                  # ('NOTES', key)
            t = NJ[p[1]]['text']
        else:
            t = RAW[p]
        c = len(re.findall(old, t, flags=re.S)) if regex else t.count(old)
        if not c: continue
        t2 = re.sub(old, new, t, flags=re.S) if regex else t.replace(old, new)
        if isinstance(p, tuple): NJ[p[1]]['text'] = t2
        else: RAW[p] = t2
        tot += c
        LOG.append((why, ('notes_zh.json #' + p[1]) if isinstance(p, tuple) else rel(p), ('(regex) ' if regex else '') + old, new if isinstance(new, str) else '(computed)', c))
    if n is not None: assert tot == n, ('count', why, old[:90], tot, n)
    assert tot >= nmin, ('rule did not apply', why, old[:90])
    return tot
def NK(*keys): return [('NOTES', k) for k in keys]
def note_keys_with(s): return [('NOTES', k) for k, v in NJ.items() if s in v['text']]
NJ = json.loads(RAW[NOTES])

